<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { apiRequest } from '@/api/client'
import { useWarehouseStore } from '@/stores/warehouse'
import { WarehouseScene } from '@/three/WarehouseScene'
import type { ParcelDetails } from '@/types/api'
import type { ParcelHover } from '@/three/HoverController'
import { dwellText } from '@/features/parcelTooltip'
const store=useWarehouseStore(),canvas=ref<HTMLElement>(),search=ref(''),hover=ref<ParcelHover|null>(null),hoverDetail=ref<ParcelDetails|null>(null),selectedDetail=ref<ParcelDetails|null>(null),outboundCode=ref(''),confirmOutbound=ref(false),busy=ref(false),actionError=ref(''),actionNotice=ref('')
const inbound=reactive({trackingNo:'',courierCompany:'顺丰',customerMobile:'13900000001',remark:'3D 快速入库'})
const route=useRoute();let scene:WarehouseScene|undefined;let hoverRequest=0
async function mount(){if(!store.snapshot)await store.refresh();await nextTick();if(canvas.value&&store.snapshot){scene?.dispose();scene=new WarehouseScene(canvas.value,store.snapshot,select,relocate3d,showHover);const id=Number(route.query.parcelId);if(id){void select(id);focus(id)}}}
function focus(id:number){const p=store.snapshot?.parcels.find(x=>x.id===id);if(p?.slotId)scene?.camera.focusParcel(p.slotId)}
function find(){const p=store.snapshot?.parcels.find(x=>x.trackingNo.toLowerCase().includes(search.value.toLowerCase()));if(p){void select(p.id);focus(p.id)}}
async function detail(id:number){return apiRequest<ParcelDetails>(`/api/parcels/${id}/details`)}
async function select(id:number){store.selectParcel(id);selectedDetail.value=await detail(id);outboundCode.value='';confirmOutbound.value=false}
async function showHover(value:ParcelHover|null){hover.value=value;if(!value){hoverDetail.value=null;return}const request=++hoverRequest,result=await detail(value.parcelId);if(request===hoverRequest&&hover.value?.parcelId===value.parcelId)hoverDetail.value=result}
async function refreshAfterMutation(){await store.refresh();if(store.selectedParcelId)selectedDetail.value=await detail(store.selectedParcelId)}
async function relocate3d(parcelId:number,slotId:number){const ok=await store.relocate(parcelId,slotId,'3d drag and snap');if(ok)await refreshAfterMutation();return ok}
async function createInbound(){busy.value=true;actionError.value='';actionNotice.value='';try{const parcel=await apiRequest<{id:number}>('/api/parcels/inbound',{method:'POST',body:JSON.stringify(inbound)});inbound.trackingNo='';actionNotice.value='快件已进入 3D 入库暂存区';await refreshAfterMutation();await select(parcel.id)}catch(e){actionError.value=e instanceof Error?e.message:'入库失败'}finally{busy.value=false}}
async function outbound(){if(!selectedDetail.value)return;if(!confirmOutbound.value){confirmOutbound.value=true;return}busy.value=true;actionError.value='';try{await apiRequest(`/api/parcels/${selectedDetail.value.parcel.id}/outbound`,{method:'POST',body:JSON.stringify({pickupCode:outboundCode.value})});actionNotice.value='快件已出库';confirmOutbound.value=false;await refreshAfterMutation()}catch(e){actionError.value=e instanceof Error?e.message:'出库失败'}finally{busy.value=false}}
const selected=computed(()=>selectedDetail.value)
onMounted(mount);watch(()=>store.lastSyncAt,mount);onBeforeUnmount(()=>scene?.dispose())
</script>
<template><section class="page twin-page"><header class="page-heading"><div><p class="eyebrow">LIVE SPATIAL MODEL</p><h1>仓库数字孪生</h1></div><div class="twin-tools"><input v-model="search" placeholder="输入运单号定位" @keyup.enter="find"><button class="ghost" @click="find">定位</button><button class="ghost" @click="scene?.camera.frontView()">正视</button><button class="ghost" @click="scene?.camera.topView()">顶视</button><button class="ghost" @click="scene?.camera.resetCamera()">全景</button></div></header><form class="twin-inbound" @submit.prevent="createInbound"><input v-model="inbound.trackingNo" required placeholder="新运单号" aria-label="3D 新运单号"><input v-model="inbound.customerMobile" required placeholder="客户手机号" aria-label="3D 客户手机号"><select v-model="inbound.courierCompany"><option>顺丰</option><option>中通</option><option>圆通</option><option>韵达</option></select><button class="primary compact" :disabled="busy">快速入库到暂存区</button><span class="success">{{actionNotice}}</span><span class="error">{{actionError}}</span></form><div class="twin-layout"><div ref="canvas" class="twin-canvas"><div v-if="hover&&hoverDetail" class="parcel-tooltip" :style="{left:`${hover.x}px`,top:`${hover.y}px`}"><b>{{hoverDetail.parcel.trackingNo}}</b><span>{{hoverDetail.parcel.courierCompany}} · {{hoverDetail.parcel.status}}</span><span>{{hoverDetail.slotCode??'入库暂存区'}}</span><span>{{hoverDetail.customer?.name??'客户未知'}} · {{hoverDetail.customer?.maskedMobile}}</span><span>到站 {{hoverDetail.parcel.arrivedAt.replace('T',' ')}}</span><span>停留 {{dwellText(hoverDetail.parcel.arrivedAt)}}</span></div></div><aside class="detail-panel"><template v-if="selected"><p class="eyebrow">SELECTED</p><h2>{{selected.parcel.trackingNo}}</h2><dl><dt>状态</dt><dd>{{selected.parcel.status}}</dd><dt>仓位</dt><dd>{{selected.slotCode??'入库暂存区'}}</dd><dt>快递</dt><dd>{{selected.parcel.courierCompany}}</dd><dt>客户</dt><dd>{{selected.customer?.name}} · {{selected.customer?.maskedMobile}}</dd><dt>取件码</dt><dd>{{selected.pickupCode}}</dd><dt>到站</dt><dd>{{selected.parcel.arrivedAt.replace('T',' ')}}</dd><dt>停留</dt><dd>{{dwellText(selected.parcel.arrivedAt)}}</dd></dl><button v-if="selected.parcel.slotId" class="primary" @click="focus(selected.parcel.id)">镜头定位</button><form v-if="selected.parcel.status==='IN_STOCK'" class="outbound-form" @submit.prevent="outbound"><input v-model="outboundCode" required placeholder="输入取件码" aria-label="3D 出库取件码"><p v-if="confirmOutbound" class="error">请再次确认：出库后该快件将离开当前仓位。</p><button class="primary" :disabled="busy">{{confirmOutbound?'再次确认出库':'确认出库'}}</button></form></template><div v-else class="empty">悬停查看摘要，点击或拖拽快件执行作业</div></aside></div></section></template>
